<?php
namespace App\Entity;
use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity]
class AffectationChantier { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne] private ?Candidat $candidat=null; #[ORM\ManyToOne] private ?Chantier $chantier=null; #[ORM\Column(type:'date')] private ?\DateTimeInterface $dateDebut=null; #[ORM\Column(type:'date',nullable:true)] private ?\DateTimeInterface $dateFin=null; #[ORM\Column(length:30)] private string $statut='EN_COURS'; public function getId():?int{return $this->id;} public function getCandidat():?Candidat{return $this->candidat;} public function setCandidat(?Candidat $v):self{$this->candidat=$v;return $this;} public function getChantier():?Chantier{return $this->chantier;} public function setChantier(?Chantier $v):self{$this->chantier=$v;return $this;} public function getDateDebut():?\DateTimeInterface{return $this->dateDebut;} public function setDateDebut(?\DateTimeInterface $v):self{$this->dateDebut=$v;return $this;} public function getDateFin():?\DateTimeInterface{return $this->dateFin;} public function setDateFin(?\DateTimeInterface $v):self{$this->dateFin=$v;return $this;} public function getStatut():string{return $this->statut;} public function setStatut(string $v):self{$this->statut=$v;return $this;} }
